mapper.select:
SELECT PC, num, MARKET, VARIABLE, VAL, VS, VS2, COMMENTS, ADD_DATE, DELETE_DATE,
       REGISTER_USER, REGISTER_DATETIME, UPDATE_USER, UPDATE_DATETIME
FROM HDOC_USER_DEFINED_RULES
WHERE 1=1



         AND PC != #{pc}
         AND PC > #{pc}
         AND PC < #{pc}
         AND PC = #{pc}





         AND num != #{num}
         AND num > #{num}
         AND num < #{num}
         AND num = #{num}





         AND MARKET != #{market}
         AND MARKET > #{market}
         AND MARKET < #{market}
         AND MARKET = #{market}





         AND VARIABLE != #{variable}
         AND VARIABLE > #{variable}
         AND VARIABLE < #{variable}
         AND VARIABLE = #{variable}





         AND VAL != #{val}
         AND VAL > #{val}
         AND VAL < #{val}
         AND VAL = #{val}





         AND VS != #{vs}
         AND VS > #{vs}
         AND VS < #{vs}
         AND VS = #{vs}





         AND VS2 != #{vsVal2}
         AND VS2 > #{vsVal2}
         AND VS2 < #{vsVal2}
         AND VS2 = #{vsVal2}





         AND COMMENTS != #{comments}
         AND COMMENTS < #{comments}
         AND COMMENTS = #{comments}





         AND ADD_DATE != #{addDate}
         AND ADD_DATE < #{addDate}
         AND ADD_DATE = #{addDate}





         AND DELETE_DATE != #{deleteDate}
         AND DELETE_DATE < #{deleteDate}
         AND DELETE_DATE = #{deleteDate}





         AND REGISTER_USER != #{createdBy}
         AND REGISTER_USER < #{createdBy}
         AND REGISTER_USER = #{createdBy}





         AND DATE(REGISTER_DATETIME) != #{date}
         AND REGISTER_DATETIME > #{date}
         AND REGISTER_DATETIME < #{date}
         AND DATE(REGISTER_DATETIME) = #{date}


ORDER BY PC, MARKET, num
